import React, { useEffect, useRef, useState } from 'react';
import { CalendarDays, ClipboardList, Plus, Wallet, Users, SlidersHorizontal, ShieldCheck, LogOut, Search, ChevronLeft, ChevronRight, ArrowUpRight, ArrowRight, Download, FileText, Pencil, Trash2, RefreshCw, X, Check, Server, Monitor, HardDrive, Clock3, Receipt, CheckCircle2, AlertCircle, Building2, LayoutGrid, List, Menu, Loader2, LockKeyhole, Sparkles } from 'lucide-react';
import { halls, hallColors, money, paid, iso, today, fmtDate, schemas, reservationSections, initialFields } from './models';
